<template>
  <view class="page certificates-page">
    <UiNavbar :back="true" title="技能证书" />
    <view class="body"><view v-if="loading" class="state-card">正在加载证书</view><view v-else-if="!products.length" class="state-card">暂无在售证书</view><view v-for="item in products" :key="item.productId" class="product-card card"><image v-if="item.coverUrl" :src="assetUrl(item.coverUrl)" class="cover" mode="aspectFill" /><view class="copy"><text class="name">{{ item.productName }}</text><text class="intro">{{ item.productIntro || '平台技能证书办理服务' }}</text><text class="price">¥{{ item.price }}</text><button class="primary-button" @click="openApply(item)">立即购买</button></view></view></view>
    <view v-if="applyVisible" class="mask"><view class="sheet"><text class="sheet-title">提交证书申请</text><text class="sheet-hint">线上不收集身份证资料，如需核验由平台线下联系。</text><input v-model="form.phone" class="input" placeholder="联系电话" type="number" maxlength="32"><input v-model="form.address" class="input" placeholder="快递地址"><view class="photo-row"><text>{{ form.photoUrl ? '电子照片已选择' : '电子照片（必填）' }}</text><button class="photo-button" @click="choosePhoto">选择照片</button></view><button class="primary-button" @click="submit">提交并支付</button><button class="cancel-button" @click="applyVisible = false">取消</button></view></view>
    <AppFeedback />
  </view>
</template>
<script setup>
import { reactive, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import UiNavbar from '@/components/ui/UiNavbar.vue'; import AppFeedback from '@/components/AppFeedback.vue'
import { createCertificateApplication, listCertificateProducts } from '@/api/business'; import { uploadFile } from '@/api/common'; import { payBusiness } from '@/composables/usePayment'; import { assetUrl } from '@/utils/assets'; import { showToast } from '@/utils/feedback'
const products = ref([]); const loading = ref(false); const applyVisible = ref(false); const selected = ref(null); const form = reactive({ phone: '', address: '', photoUrl: '' })
onShow(load)
async function load () { loading.value = true; try { const response = await listCertificateProducts(); products.value = response.data || response || [] } finally { loading.value = false } }
function openApply (item) { selected.value = item; form.phone = ''; form.address = ''; form.photoUrl = ''; applyVisible.value = true }
async function choosePhoto () { try { const result = await uni.chooseImage({ count: 1, sizeType: ['compressed'], sourceType: ['album', 'camera'] }); const path = result?.tempFilePaths?.[0]; if (!path) return; const response = await uploadFile(path); form.photoUrl = response?.url || response?.data?.url || ''; if (!form.photoUrl) throw new Error('上传未返回图片地址') } catch (e) { if (!String(e?.errMsg || e?.message || '').includes('cancel')) showToast(e.message || '照片上传失败') } }
async function submit () { if (!form.phone.trim() || !form.address.trim() || !form.photoUrl) return showToast('请填写联系电话、快递地址并上传电子照片'); try { const response = await createCertificateApplication({ productId: selected.value.productId, ...form }); const app = response.data || response; await payBusiness('C', app.applicationId); applyVisible.value = false; showToast('支付成功，申请已提交') } catch (e) { showToast(e.message || '购买失败') } }
</script>
<style lang="scss" scoped>@import '@/styles/tokens.scss'; .body{padding:24rpx}.card{display:flex;margin-bottom:20rpx;padding:22rpx;border-radius:22rpx;background:#fff;box-shadow:$shadow-card}.cover{width:150rpx;height:150rpx;margin-right:20rpx;border-radius:16rpx;background:$bg-sunken}.copy{flex:1}.name{display:block;font-size:32rpx;font-weight:700;color:$ink-900}.intro{display:block;margin-top:12rpx;font-size:24rpx;color:$ink-400}.price{display:block;margin-top:14rpx;font-size:34rpx;font-weight:700;color:$brand-500}.primary-button{margin:16rpx 0 0;border:0;border-radius:999rpx;line-height:72rpx}.state-card{text-align:center;color:$ink-400}.mask{position:fixed;inset:0;z-index:30;display:flex;align-items:flex-end;background:rgba(0,0,0,.35)}.sheet{width:100%;padding:34rpx 28rpx calc(34rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.sheet-title{display:block;font-size:34rpx;font-weight:700;color:$ink-900}.sheet-hint{display:block;margin:12rpx 0 20rpx;font-size:24rpx;color:$ink-400}.input{height:82rpx;margin-bottom:16rpx;padding:0 20rpx;border-radius:14rpx;background:$bg-sunken}.photo-row{display:flex;align-items:center;justify-content:space-between;margin:6rpx 0 12rpx;color:$ink-500;font-size:26rpx}.photo-button{margin:0;border:0;border-radius:999rpx;background:#fff3ed;color:$brand-500;font-size:25rpx}.cancel-button{margin-top:18rpx;border:0;background:transparent;color:$ink-500}
</style>
